// SellerServiceHandler is an implementation of the hawkr.seller.SellerService service.
type SellerServiceHandler interface {
	// 獲取商家信息
	GetSeller(context.Context, *connect.Request[seller.GetSellerRequest]) (*connect.Response[seller.SellerResponse], error)
	// 輕量版 store_id → account_id 解析：只回 account_id，不像 GetSeller(store_id=x)
	// 要組整份 profile。供 gateway admin 端點吃 :store_id path param、但下游呼叫
	// 仍是 account_id-keyed（如手動停權 gRPC 系列）時使用。查無此 store_id 回
	// gRPC NotFound（本 RPC 回應無 code/message 欄位，錯誤走真實 gRPC status）。
	ResolveSellerAccountID(context.Context, *connect.Request[seller.ResolveSellerAccountIDRequest]) (*connect.Response[seller.ResolveSellerAccountIDResponse], error)
	GetCurrentStoreID(context.Context, *connect.Request[seller.GetCurrentStoreIDRequest]) (*connect.Response[seller.GetCurrentStoreIDResponse], error)
	// 根據會員ID獲取商家
	GetSellerByMemberId(context.Context, *connect.Request[seller.GetSellerByMemberIdRequest]) (*connect.Response[seller.SellerResponse], error)
	// 根據 UserID 獲取商家
	GetSellerByUserId(context.Context, *connect.Request[seller.GetSellerByUserIdRequest]) (*connect.Response[seller.SellerResponse], error)
	// 批量獲取商家
	GetSellerBatch(context.Context, *connect.Request[seller.GetSellerBatchRequest]) (*connect.Response[seller.SellerBatchResponse], error)
	// 驗證商家狀態
	ValidateSeller(context.Context, *connect.Request[seller.ValidateSellerRequest]) (*connect.Response[seller.ValidateSellerResponse], error)
	// 獲取商家統計
	GetSellerStats(context.Context, *connect.Request[seller.GetSellerStatsRequest]) (*connect.Response[seller.SellerStatsResponse], error)
	// ========== PAYUNi 金流整合 ==========
	// 觸發 PAYUNi 商家註冊
	RegisterPayuni(context.Context, *connect.Request[seller.RegisterPayuniRequest]) (*connect.Response[seller.PayuniStatusResponse], error)
	// 查詢 PAYUNi 註冊狀態
	GetPayuniStatus(context.Context, *connect.Request[seller.GetPayuniStatusRequest]) (*connect.Response[seller.PayuniStatusResponse], error)
	// 重試 PAYUNi 註冊
	RetryPayuniRegistration(context.Context, *connect.Request[seller.RetryPayuniRequest]) (*connect.Response[seller.PayuniStatusResponse], error)
	// 手動刷新 PAYUNi 審核狀態
	RefreshPayuniStatus(context.Context, *connect.Request[seller.RefreshPayuniStatusRequest]) (*connect.Response[seller.PayuniStatusResponse], error)
	// 更新商家 PAYUNi 聯絡/地址資料（issue #2806 Phase 2 deny-by-default allowlist）
	UpdateMerchantProfile(context.Context, *connect.Request[seller.UpdateMerchantProfileRequest]) (*connect.Response[seller.UpdateMerchantProfileResponse], error)
	// 獲取商家 PAYUNi 配置（供 payment-service 使用）
	GetSellerPayuniConfig(context.Context, *connect.Request[seller.GetSellerPayuniConfigRequest]) (*connect.Response[seller.SellerPayuniConfigResponse], error)
	// 判斷政府查驗回的「業者名稱」是否屬於這個賣家（19 號設計書 §8.5.1，供 product-service 使用）。
	//
	// 🔴 比對在本服務內部完成，只回布林與命中欄位名：real_name 是 PII
	//    （18 號設計書列為明文保留欄），不得跨服務傳輸。
	MatchCertificateHolder(context.Context, *connect.Request[seller.MatchCertificateHolderRequest]) (*connect.Response[seller.MatchCertificateHolderResponse], error)
	// 創建商家 (Apply)
	CreateSeller(context.Context, *connect.Request[seller.CreateSellerRequest]) (*connect.Response[seller.SellerResponse], error)
	// 更新商家
	UpdateSeller(context.Context, *connect.Request[seller.UpdateSellerRequest]) (*connect.Response[seller.SellerResponse], error)
	UpdateSellerSEO(context.Context, *connect.Request[seller.UpdateSellerSEORequest]) (*connect.Response[seller.UpdateSellerSEOResponse], error)
	UpdateSellerFoodRegistration(context.Context, *connect.Request[seller.UpdateSellerFoodRegistrationRequest]) (*connect.Response[seller.UpdateSellerFoodRegistrationResponse], error)
	// 完成 Onboarding（填寫或略過）
	CompleteOnboarding(context.Context, *connect.Request[seller.CompleteOnboardingRequest]) (*connect.Response[seller.SellerResponse], error)
	// 更新商家 logo（透過 staged token）
	UpdateLogo(context.Context, *connect.Request[seller.UpdateLogoRequest]) (*connect.Response[seller.UpdateLogoResponse], error)
	// 更新商家封面圖片（透過 staged token）
	UpdateCover(context.Context, *connect.Request[seller.UpdateCoverRequest]) (*connect.Response[seller.UpdateCoverResponse], error)
	// ========== Certification: Old API (Deprecated) ==========
	GetCertificationDraft(context.Context, *connect.Request[seller.GetDraftRequest]) (*connect.Response[seller.CertificationDraftResponse], error)
	SaveCertificationDraft(context.Context, *connect.Request[seller.SaveDraftRequest]) (*connect.Response[seller.CertificationDraftResponse], error)
	SubmitCertification(context.Context, *connect.Request[seller.SubmitCertificationRequest]) (*connect.Response[seller.CertificationDraftResponse], error)
	// ========== Certification: New API ==========
	// Draft management
	CreateCertificationDraft(context.Context, *connect.Request[seller.CreateCertificationDraftRequest]) (*connect.Response[seller.CertificationApplicationResponse], error)
	SaveCertificationProgress(context.Context, *connect.Request[seller.SaveCertificationProgressRequest]) (*connect.Response[seller.CertificationApplicationResponse], error)
	CancelCertification(context.Context, *connect.Request[seller.CancelCertificationRequest]) (*connect.Response[seller.CertificationApplicationResponse], error)
	// Submission
	SubmitCertificationApplication(context.Context, *connect.Request[seller.SubmitCertificationApplicationRequest]) (*connect.Response[seller.CertificationApplicationResponse], error)
	// Query
	GetCertificationApplication(context.Context, *connect.Request[seller.GetCertificationApplicationRequest]) (*connect.Response[seller.CertificationApplicationResponse], error)
	// 統一編號查詢（GCIS 經濟部商業司公開資料，autofill 公司資料用）
	LookupBusinessRegistration(context.Context, *connect.Request[seller.LookupBusinessRegistrationRequest]) (*connect.Response[seller.LookupBusinessRegistrationResponse], error)
	// 地址模糊搜尋 / 驗證（proxy 至 Google Maps，透過 pkg/geocode ACL；賣家門市地址用）
	SuggestAddress(context.Context, *connect.Request[seller.SuggestAddressRequest]) (*connect.Response[seller.SuggestAddressResponse], error)
	ValidateAddress(context.Context, *connect.Request[seller.ValidateAddressRequest]) (*connect.Response[seller.ValidateAddressResponse], error)
	// Review operations (for admin backend)
	ApproveCertification(context.Context, *connect.Request[seller.ApproveCertificationRequest]) (*connect.Response[seller.ReviewResponse], error)
	RejectCertification(context.Context, *connect.Request[seller.RejectCertificationRequest]) (*connect.Response[seller.ReviewResponse], error)
	GetCertificationReviews(context.Context, *connect.Request[seller.GetCertificationReviewsRequest]) (*connect.Response[seller.CertificationReviewsResponse], error)
	// ========== Admin: Seller Management ==========
	ListSellersForAdmin(context.Context, *connect.Request[seller.ListSellersForAdminRequest]) (*connect.Response[seller.ListSellersForAdminResponse], error)
	// 賣家統計走獨立 RPC，不內嵌在列表回應裡：這五個數字是全站聚合、不隨分頁
	// 改變，內嵌等於每次翻頁都重算五個全表 COUNT，且前端要拿統計就得先發一個
	// ?page=1&limit=1 的假查詢。與 GetAccountStatsForAdmin / GetBuyerStatsForAdmin 同形。
	GetSellerStatsForAdmin(context.Context, *connect.Request[seller.GetSellerStatsForAdminRequest]) (*connect.Response[seller.GetSellerStatsForAdminResponse], error)
	// ========== Admin: Certification Management ==========
	ListCertificationsForAdmin(context.Context, *connect.Request[seller.ListCertificationsForAdminRequest]) (*connect.Response[seller.ListCertificationsForAdminResponse], error)
	// Admin certification detail — returns the FULL id_card_no (§5.1 角色分離；
	// 賣家 GetCertificationApplication 回遮蔽值，admin 走此 RPC 回完整值, #608)。
	GetCertificationApplicationForAdmin(context.Context, *connect.Request[seller.GetCertificationApplicationForAdminRequest]) (*connect.Response[seller.CertificationApplicationResponse], error)
	// ========== Cross-Service: Seller Meta ==========
	// 批量獲取商家元資料（輕量：名稱+Logo+狀態），回傳 Map<account_id, SellerMeta>
	BatchGetSellerMeta(context.Context, *connect.Request[seller.BatchGetSellerMetaRequest]) (*connect.Response[seller.BatchGetSellerMetaResponse], error)
	// 公開商品城市篩選用：只回符合城市且可公開販售之 current store ids，不暴露賣家 PII。
	ListPublicStoreIDsByCity(context.Context, *connect.Request[seller.ListPublicStoreIDsByCityRequest]) (*connect.Response[seller.ListPublicStoreIDsByCityResponse], error)
	// 一次回傳 canonical 22 縣市與完整 public store ids，供 product 聚合；不含 PII。
	ListPublicStoresByCity(context.Context, *connect.Request[seller.ListPublicStoresByCityRequest]) (*connect.Response[seller.ListPublicStoresByCityResponse], error)
	// ========== Cross-Role Guards: Principal Resolution ==========
	// 解析 store_id → 登入 principal account_id（Plan 2b，供 order/cart/coupon/im/social 5 個 cross-role
	// guard 用）。只解析存活（沒有關閉）的店家；其餘的 id（已關閉或不存在）不在 principals 裡，只出現在 unresolved_ids。
	ResolvePrincipals(context.Context, *connect.Request[seller.ResolvePrincipalsRequest]) (*connect.Response[seller.ResolvePrincipalsResponse], error)
	// ========== Cross-Service: Historical Stint Enumeration (internal-use only) ==========
	// 回傳該帳號名下「所有」store_id stint（不論 is_current，含已關閉）。唯一用途：
	// account.deleted/buyer.deleted PII 清除 consumer（im-service）逐一枚舉歷史
	// store_id 清 messages.sender_id（買家 store-stint rekey W2/W3 D8）。不透過
	// gateway 暴露，僅供服務間 gRPC 呼叫。
	ListStoreIDsByAccount(context.Context, *connect.Request[seller.ListStoreIDsByAccountRequest]) (*connect.Response[seller.ListStoreIDsByAccountResponse], error)
	// ========== Cross-Service: Shipping Profile ==========
	// 取得賣家寄件資訊（Shipping Service 建立物流單用）
	GetSellerShippingProfile(context.Context, *connect.Request[seller.GetSellerShippingProfileRequest]) (*connect.Response[seller.GetSellerShippingProfileResponse], error)
	// ========== Store Visitors ==========
	// 記錄訪客（買家瀏覽賣家商店頁時 fire-and-forget 呼叫）
	RecordStoreVisit(context.Context, *connect.Request[seller.RecordStoreVisitRequest]) (*connect.Response[seller.RecordStoreVisitResponse], error)
	// 取得商店訪客列表（賣家查看誰來看過）
	GetStoreVisitors(context.Context, *connect.Request[seller.GetStoreVisitorsRequest]) (*connect.Response[seller.StoreVisitorListResponse], error)
	// ========== Product View Stats ==========
	// 記錄商品被瀏覽（網頁匿名路徑，APP 路徑走 MQ）
	RecordProductView(context.Context, *connect.Request[seller.RecordProductViewRequest]) (*connect.Response[seller.RecordProductViewResponse], error)
	// 取得賣家旗下所有商品總瀏覽數與週環比（Dashboard 用）
	GetProductViewStats(context.Context, *connect.Request[seller.GetProductViewStatsRequest]) (*connect.Response[seller.ProductViewStatsResponse], error)
	// ========== Recommended Sellers ==========
	// 取得推薦商家列表（依營收排名，組合 Order Service 資料）
	GetRecommendedSellers(context.Context, *connect.Request[seller.GetRecommendedSellersRequest]) (*connect.Response[seller.GetRecommendedSellersResponse], error)
	// ========== Self-Service: Account Deletion ==========
	// 賣家自行申請刪除帳號（或管理員代刪）
	DeleteSellerAccount(context.Context, *connect.Request[seller.DeleteSellerAccountRequest]) (*connect.Response[seller.DeleteSellerAccountResponse], error)
	// 登入端商家違規檢舉（買家 / 賣家）
	CreateViolationReport(context.Context, *connect.Request[seller.CreateViolationReportRequest]) (*connect.Response[seller.CreateViolationReportResponse], error)
	// 檢舉者查自己提交的檢舉
	ListMyViolationReports(context.Context, *connect.Request[seller.ListMyViolationReportsRequest]) (*connect.Response[seller.ListMyViolationReportsResponse], error)
	// 公開無登入食安通報（gateway 走 anonymous 路由，雙層 IP rate limit）
	CreateFoodSafetyReport(context.Context, *connect.Request[seller.CreateFoodSafetyReportRequest]) (*connect.Response[seller.CreateFoodSafetyReportResponse], error)
	// 賣家側
	SellerListMyViolations(context.Context, *connect.Request[seller.SellerListMyViolationsRequest]) (*connect.Response[seller.SellerListMyViolationsResponse], error)
	SellerSubmitAppeal(context.Context, *connect.Request[seller.SellerSubmitAppealRequest]) (*connect.Response[seller.SellerSubmitAppealResponse], error)
	SellerGetAppeal(context.Context, *connect.Request[seller.SellerGetAppealRequest]) (*connect.Response[seller.SellerGetAppealResponse], error)
	// 公開賣家頁查詢過去 90 天 high+ 違規（D8 Redis cache）
	GetPublicSellerViolations(context.Context, *connect.Request[seller.GetPublicSellerViolationsRequest]) (*connect.Response[seller.GetPublicSellerViolationsResponse], error)
	// Admin 治理
	AdminListViolationReports(context.Context, *connect.Request[seller.AdminListViolationReportsRequest]) (*connect.Response[seller.AdminListViolationReportsResponse], error)
	AdminPatchSellerViolationReportStatus(context.Context, *connect.Request[seller.AdminPatchReportStatusRequest]) (*connect.Response[seller.AdminPatchReportStatusResponse], error)
	AdminPatchFoodSafetyReportStatus(context.Context, *connect.Request[seller.AdminPatchReportStatusRequest]) (*connect.Response[seller.AdminPatchReportStatusResponse], error)
	AdminAcknowledgeFoodSafetyReport(context.Context, *connect.Request[seller.AdminAcknowledgeRequest]) (*connect.Response[seller.AdminAcknowledgeResponse], error)
	AdminGenerateFDAReport(context.Context, *connect.Request[seller.AdminGenerateFDAReportRequest]) (*connect.Response[seller.AdminGenerateFDAReportResponse], error)
	AdminMarkFDAReported(context.Context, *connect.Request[seller.AdminMarkFDAReportedRequest]) (*connect.Response[seller.AdminMarkFDAReportedResponse], error)
	AdminNotifySeller(context.Context, *connect.Request[seller.AdminNotifySellerRequest]) (*connect.Response[seller.AdminNotifySellerResponse], error)
	AdminCreateViolation(context.Context, *connect.Request[seller.AdminCreateViolationRequest]) (*connect.Response[seller.AdminCreateViolationResponse], error)
	// Admin 決議申訴前查看 violation 詳情（含 appeal_evidence_asset_ids，issue #1516）
	AdminGetViolation(context.Context, *connect.Request[seller.AdminGetViolationRequest]) (*connect.Response[seller.AdminGetViolationResponse], error)
	AdminUpdateViolation(context.Context, *connect.Request[seller.AdminUpdateViolationRequest]) (*connect.Response[seller.AdminUpdateViolationResponse], error)
	AdminRevokeViolation(context.Context, *connect.Request[seller.AdminRevokeViolationRequest]) (*connect.Response[seller.AdminRevokeViolationResponse], error)
	AdminDecideAppeal(context.Context, *connect.Request[seller.AdminDecideAppealRequest]) (*connect.Response[seller.AdminDecideAppealResponse], error)
	// ========== Admin 手動停權（不服勸導，32 §13 / 46 §5） ==========
	SuspendSellerForAdmin(context.Context, *connect.Request[seller.SuspendSellerForAdminRequest]) (*connect.Response[seller.SuspendSellerForAdminResponse], error)
	LiftSellerSuspensionForAdmin(context.Context, *connect.Request[seller.LiftSellerSuspensionForAdminRequest]) (*connect.Response[seller.LiftSellerSuspensionForAdminResponse], error)
	ListSellerSuspensionsForAdmin(context.Context, *connect.Request[seller.ListSellerSuspensionsForAdminRequest]) (*connect.Response[seller.ListSellerSuspensionsForAdminResponse], error)
	GetActiveSellerSuspensionForAdmin(context.Context, *connect.Request[seller.GetActiveSellerSuspensionForAdminRequest]) (*connect.Response[seller.GetActiveSellerSuspensionForAdminResponse], error)
	// ========== Admin 賣家會員分級方案（子系統 1）==========
	AssignSellerMembershipPlan(context.Context, *connect.Request[seller.AssignSellerMembershipPlanRequest]) (*connect.Response[seller.SellerMembershipPlanResponse], error)
	GetSellerMembershipPlan(context.Context, *connect.Request[seller.GetSellerMembershipPlanRequest]) (*connect.Response[seller.SellerMembershipPlanResponse], error)
	// Admin：方案目錄本身（cap/price/is_purchasable）的讀寫，比照買家 membership_plans
	// 目錄的 ListMembershipPlans/UpdateMembershipPlan 慣例。tier_rank 不開放編輯——它
	// 決定 candidate_platform_lane.go 的 AI 排序權重，風險層級與 cap/price 不同。
	ListSellerMembershipPlans(context.Context, *connect.Request[seller.ListSellerMembershipPlansRequest]) (*connect.Response[seller.ListSellerMembershipPlansResponse], error)
	UpdateSellerMembershipPlan(context.Context, *connect.Request[seller.UpdateSellerMembershipPlanRequest]) (*connect.Response[seller.UpdateSellerMembershipPlanResponse], error)
	// ========== 站外業者主檔（招商名單） ==========
	// 供 ai-service 的 EXTERNAL lane 與舊「AI 找貨」工具查詢站外業者。
	//
	// 🔴 一列即一業者：呼叫端不得再做任何去重。已入駐（CONVERTED）與已封存
	//    （ARCHIVED）的業者由本服務端過濾掉——已入駐者出現在「找平台外的
	//    業者」本來就是錯的，那不是去重問題。
	//
	// 相關性分數不在本 RPC 計算：回傳命中的 facet 旗標與可評分的文字欄位，
	// 由呼叫端自行加權排序（procurement 的 tier 加權與曝光門檻屬 ai-service）。
	SearchSellerProspects(context.Context, *connect.Request[seller.SearchSellerProspectsRequest]) (*connect.Response[seller.SearchSellerProspectsResponse], error)
	// 建立一筆站外業者。識別鍵的正規化與分層比對一律發生在本服務端——
	// 呼叫端（一次性遷移腳本、階段二的 admin console）只送原始欄位。
	CreateSellerProspect(context.Context, *connect.Request[seller.CreateSellerProspectRequest]) (*connect.Response[seller.CreateSellerProspectResponse], error)
	// ========== 站外業者主檔 — Admin console（階段二） ==========
	// 與上面兩支的差別在投影：這一組回 AdminSellerProspectItem（含 status、
	// tax_id、稽核欄位），呼叫端只有 gateway 的 /admin namespace。
	// 不共用 SellerProspectItem——那個型別的消費端包含 ai-service，而
	// toProspectSearchItemPB 的窄投影清單不能繼續成長。
	AdminListSellerProspects(context.Context, *connect.Request[seller.AdminListSellerProspectsRequest]) (*connect.Response[seller.AdminListSellerProspectsResponse], error)
	AdminGetSellerProspect(context.Context, *connect.Request[seller.AdminGetSellerProspectRequest]) (*connect.Response[seller.AdminGetSellerProspectResponse], error)
	AdminUpdateSellerProspect(context.Context, *connect.Request[seller.AdminUpdateSellerProspectRequest]) (*connect.Response[seller.AdminGetSellerProspectResponse], error)
	AdminArchiveSellerProspect(context.Context, *connect.Request[seller.AdminArchiveSellerProspectRequest]) (*connect.Response[seller.AdminGetSellerProspectResponse], error)
	AdminListDuplicateProspects(context.Context, *connect.Request[seller.AdminListDuplicateProspectsRequest]) (*connect.Response[seller.AdminListDuplicateProspectsResponse], error)
	AdminMergeSellerProspects(context.Context, *connect.Request[seller.AdminMergeSellerProspectsRequest]) (*connect.Response[seller.AdminMergeSellerProspectsResponse], error)
	AdminConvertSellerProspect(context.Context, *connect.Request[seller.AdminConvertSellerProspectRequest]) (*connect.Response[seller.AdminGetSellerProspectResponse], error)
	// 換一張品牌圖片。kind 決定 logo 還是 cover，兩者各自獨立一組欄位。
	// 回應與 AdminGetSellerProspect 同型別：Admin 收到後會逐項核對 key／version／
	// source_url 才認定存檔成功，少回欄位等同存檔失敗。
	AdminUpdateSellerProspectMedia(context.Context, *connect.Request[seller.AdminUpdateSellerProspectMediaRequest]) (*connect.Response[seller.AdminGetSellerProspectResponse], error)
	AdminListProspectTaxIdMatches(context.Context, *connect.Request[seller.AdminListProspectTaxIdMatchesRequest]) (*connect.Response[seller.AdminListProspectTaxIdMatchesResponse], error)
	AdminCreateProspectInvite(context.Context, *connect.Request[seller.AdminCreateProspectInviteRequest]) (*connect.Response[seller.AdminCreateProspectInviteResponse], error)
	AdminRevokeProspectInvite(context.Context, *connect.Request[seller.AdminRevokeProspectInviteRequest]) (*connect.Response[seller.AdminRevokeProspectInviteResponse], error)
	// 建立或重取一個 RFQ 收件人的邀請，回明文 secret（只此一次）。結果：
	//   - 成功：invite_id（邀請的 UUID）、secret、invited_email。
	//   - InvalidArgument：prospect_id、rfq_recipient_id 不是十進位正整數，expires_at 不是 RFC3339 或不在允許範圍內（要晚於現在且不超過
	//     上限），或這個 rfq_recipient_id 的邀請已屬於別的業者。
	//   - NotFound：業者不存在。
	//   - AlreadyExists：這張邀請的 secret 已標記寄出（不帶 reason）。
	//   - FailedPrecondition，ErrorInfo.reason 是 VendorPortalInviteErrorReason 的名稱：
	//     INVITE_REVOKED（邀請已撤銷）、PROSPECT_NOT_ACTIVE（業者不是進行中）、NO_DELIVERABLE_EMAIL（沒有可寄送的 email）。
	//   - 其他錯誤：Internal。
	EnsureVendorPortalInvite(context.Context, *connect.Request[seller.EnsureVendorPortalInviteRequest]) (*connect.Response[seller.EnsureVendorPortalInviteResponse], error)
	// 記下 secret 對應的信已寄出。結果：
	//   - 成功：code 0；同一把 secret 重複標記冪等。
	//   - InvalidArgument：invite_id 不是 UUID，或 secret 是空字串或格式不正確。
	//   - NotFound：邀請不存在。
	//   - Aborted，ErrorInfo.reason 是 INVITE_SECRET_SUPERSEDED：secret 已被之後的 Ensure 換掉，標記不生效，寄出的連結已失效。
	//   - 其他錯誤：Internal。
	MarkVendorPortalInviteSecretDelivered(context.Context, *connect.Request[seller.MarkVendorPortalInviteSecretDeliveredRequest]) (*connect.Response[seller.MarkVendorPortalInviteSecretDeliveredResponse], error)
}

